import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def check_n(n):
    # n must be coprime to 6
    if math.gcd(n, 6) != 1:
        return False

    # Valid range for a: n/3 < a <= n/2
    a_min = math.floor(n / 3) + 1
    a_max = math.floor(n / 2)

    if a_min > a_max:
        # This happens for small n, e.g., n=2, 3, 4, 5. But since we checked gcd(n, 6)=1, n >= 5.
        # For n=5, a_min=2, a_max=2. It's fine.
        return False 

    for a in range(a_min, a_max + 1):
        D = n - 2 * a  # D = n - 2a

        # The condition is $\binom{a-1}{D-1} \equiv 0 \pmod D$.

        # Case D=1: Condition is $\binom{a-1}{0} \equiv 0 \pmod 1$. Always true.
        if D == 1:
            continue

        # Case D>1: We check the congruence.
        # Binomial coefficient index k = D - 1 = n - 2a - 1.
        # N = a - 1.

        try:
            C = combinations(a - 1, D - 1)
        except ValueError:
            # Should not happen given constraints, but safe guard.
            return False

        if C % D != 0:
            # Condition failed for this specific a
            return False

    # If all checks passed for all valid 'a'
    return True

count = 0
for n in range(2, 200):
    if check_n(n):
        count += 1

print(f"The count of such integers n < 200 is: {count}")
